insert into public.stages (id, course_id, title, summary, source_url, source_label, sort_order) values ($qa$ib-m4$qa$, $qa$ib$qa$, $qa$Metode Searching 2$qa$, $qa$<h3>Uninformed Search (Blind Search)</h3>
<table border="1" cellpadding="6"><tr><th>Algoritma</th><th>Cara kerja</th><th>Complete</th><th>Optimal</th><th>Catatan</th></tr>
<tr><td><strong>BFS</strong></td><td>Jelajah level per level dari akar</td><td>Ya</td><td>Ya (biaya langkah sama)</td><td>Boros memori</td></tr>
<tr><td><strong>DFS</strong></td><td>Susuri sedalam mungkin, lalu backtrack</td><td>Tidak</td><td>Tidak</td><td>Hemat memori</td></tr>
<tr><td><strong>UCS</strong></td><td>Priority queue berdasar biaya kumulatif terkecil</td><td>Ya</td><td>Ya (biaya minimum)</td><td>Untuk bobot tak seragam</td></tr>
<tr><td><strong>DLS</strong></td><td>DFS dengan batas kedalaman L</td><td>Tidak*</td><td>Tidak</td><td>*gagal jika solusi lebih dalam dari L</td></tr>
<tr><td><strong>IDS</strong></td><td>DLS berulang dengan L naik bertahap</td><td>Ya</td><td>Ya</td><td>Memori hemat seperti DFS</td></tr></table>
<h3>Informed Search (Heuristic Search)</h3>
<ul><li><strong>Heuristik h(n)</strong>: estimasi biaya/jarak dari simpul n ke goal</li><li><strong>Greedy Best-First Search</strong>: selalu pilih h(n) terkecil &mdash; cepat tapi <strong>tidak optimal</strong> (bisa terjebak jalur yang &ldquo;terlihat dekat&rdquo;)</li><li><strong>A*</strong>: f(n) = g(n) + h(n), gabungan UCS + Greedy &mdash; <strong>optimal jika h(n) admissible</strong></li><li><strong>Admissible</strong>: h(n) tidak pernah melebih-lebihkan biaya sebenarnya</li></ul>
<h3>Poin yang Sering Keluar di Ujian</h3>
<ul><li>Hitung f(n) = g(n) + h(n) dan tentukan urutan ekspansi simpul (contoh kasus peta Jawa: Bandung &rarr; Yogyakarta)</li><li>Tentukan apakah suatu h(n) admissible atau tidak</li><li>Pilih algoritma sesuai kebutuhan: memori terbatas tapi butuh optimal &rarr; IDS; biaya langkah tak seragam &rarr; UCS/A*</li></ul>$qa$, $qa$https://drive.google.com/file/d/19y3tM0qBpeabF8EiczbDjDVjfzExPQeT/view$qa$, $qa$PDF ASLI — GOOGLE DRIVE$qa$, 4) on conflict (id) do update set course_id = excluded.course_id, title = excluded.title, summary = excluded.summary, source_url = excluded.source_url, source_label = excluded.source_label, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s1$qa$, $qa$ib-m4$qa$, $qa$Review Algoritma Searching (Search Strategies)$qa$, $qa$<p>Review Algoritma Searching (Search Strategies) 1. Uninformed Search (Blind Search): Algoritma ini tidak punya pengetahuan tambahan selain definisi masalah. Kesannya seperti “mencoba-coba” solusi. ○ Contoh: Breadth-First Search (BFS), Depth-First Search (DFS), Uniform Cost Search, Depth-Limited Search 2. Informed Search (Heuristic Search): Algoritma yang menggunakan pengetahuan tambahan Untuk pertemuan ini, berupa heuristik untuk mempercepat pencarian solusi. ○ Contoh: Greedy Search, Best-First Search, A* Search kita akan fokus pada metode ini 3. Local Search: Algoritma tidak menjelajahi seluruh ruang keadaan, tapi melakukan memperbaiki solusi sementara untuk mendapatkan solusi yang optimal ○ Contoh: Genetic Algorithm, Hill Climbing, Simulated Annealing 4. Adversarial Search: Algoritma berada di lingkungan kompetitif, dimana agen saling berlawanan. ○ Contoh: Minimax, Alpha-Beta Pruning 5. Constraint Satisfaction Problem (CSP): Algoritma yang menyelesaikan masalah dengan cara memenuhi sekumpulan batasan (constraints). ○ Contoh: Backtracking, Forward Checking, Arc-Consistency *Beberapa algoritma sudah pernah dibahas di mata kuliah Strategi Algoritma Inteligensi Buatan 2026 2</p>
<p>Outline Materi Hari Ini • Review Uninformed Search (Blind Search) ○ Breadth-First Search (BFS), ○ Depth-First Search (DFS), ○ Uniform Cost Search, ○ Depth-Limited Search, ○ Iterative Deepening Search (IDS) • Review Informed Search (Heuristic Search) ○ Greedy Best-First Search, ○ A* Search Inteligensi Buatan 2026 3</p>
<p>Uninformed Search (Blind Search) Inteligensi Buatan 2026 4</p>
<p>Uninformed Search (Blind Search) Uninformed Search atau sering disebut juga Blind Search adalah strategi pencarian dalam dimana agen tidak memiliki informasi tambahan tentang tujuan selain yang diberikan dalam definisi masalah. Sehingga, informasi yang agen ketahui hanyalah - keadaan awal (initial state), - keadaan tujuan (goal state), - dan aturan aksi yang bisa diambil. Inteligensi Buatan 2026 5</p>
<p>Uninformed Search (Blind Search) Karakteristik Uninformed Search: 1. Tidak menggunakan heuristik, tidak ada perkiraan jarak atau biaya ke tujuan. 2. Hanya berdasarkan eksplorasi ruang keadaan (state space). 3. Lengkap jika ruang keadaan terbatas dan solusi ada. 4. Tidak selalu efisien, karena sering mengeksplorasi jalur yang tidak relevan. Inteligensi Buatan 2026 6</p>$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s2$qa$, $qa$ib-m4$qa$, $qa$Uninformed Search (Blind Search)$qa$, $qa$<p>Uninformed Search (Blind Search) Jenis-jenis Uninformed Search: 1. Breadth-First Search (BFS) 2. Depth-First Search (DFS) 3. Uniform Cost Search (UCS) 4. Depth-Limited Search (DLS) 5. Iterative Deepening Search (IDS) Inteligensi Buatan 2026 7</p>
<p>Breadth-First Search (BFS) Breadth-First Search (BFS) adalah algoritma yang menjelajahi ruang pencarian secara mendatar (level demi level) mulai dari simpul akar ke semua simpul tetangganya dalam satu level. Lalu, menelusuri ke simpul di level selanjutnya, dan seterusnya sampai menemukan solusi. Sifat: ● Complete: Ya, selama b terbatas ● Optimal: Ya, jika langkah = biaya ● Kompleksitas waktu: Tidak efisien untuk pohon berderajat tinggi ● Kompleksitas ruang: Boros ruang Inteligensi Buatan 2026 8</p>
<p>Breadth-First Search (BFS) Ilustrasi: ● Mulai dari simpul akar: A ● Kunjungi semua anak level 1: B, C, D ● Lanjut ke level 2: E, F, G ● Berhenti jika menemukan goal. Rute: A→B→C→D→E→F→G Inteligensi Buatan 2026 9</p>
<p>Breadth-First Search (BFS) Iterasi V Inisialisasi 1 Iterasi 1 Q Dikunjungi 1 2 3 4 5 6 7 8 {1} T F F F F F F F 1 {2,3} T T T F F F F F Iterasi 2 2 {3,4,5} T T T T T F F F Iterasi 3 3 {4,5,6,7} T T T T T T T F Iterasi 4 4 {5,6,7,8} T T T T T T T T Iterasi 5 5 {6,7,8} T T T T T T T T Iterasi 6 6 {7,8} T T T T T T T T Iterasi 7 7 {8} T T T T T T T T Iterasi 8 8 {} T T T T T T T T Urutan simpul2 yang dikunjungi: 1, 2, 3, 4, 5, 6, 7, 8 Inteligensi Buatan 2026 10</p>
<p>Depth-First Search (DFS) Depth-First Search (DFS) adalah algoritma yang menjelajahi ruang pencarian dengan cara menyusuri jalur sedalam mungkin terlebih dahulu sebelum melakukan backtracking untuk mencoba jalur lain. Sifat: ● Complete: Tidak, jika kedalaman tak hingga ● Optimal: Tidak, solusi belum tentu paling optimal ● Kompleksitas waktu: Tidak efisien untuk pohon kedalaman tingkat tinggi ● Kompleksitas ruang: Lebih baik dari BFS Inteligensi Buatan 2026 11</p>$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s3$qa$, $qa$ib-m4$qa$, $qa$Depth-First Search (DFS)$qa$, $qa$<p>Depth-First Search (DFS) Ilustrasi: ● Mulai dari simpul akar: A ● Kunjungi simpul anak dimulai dari kiri: B ● Ulangi proses sampai mencapai simpul daun: E ● Jika mencapai simpul daun, maka lakukan runut-balik (backtracking) ke simpul terakhir yang dikunjungi sebelumnya dan mempunyai simpul anak yang belum dikunjungi: B, F ● Ulangi proses sampai menemukan goal. Rute: A→B→E→F→C→D→G Inteligensi Buatan 2026 12</p>
<p>DFS vs BFS Inteligensi Buatan 2026 13</p>
<p>Pohon Ruang Status Pencarian solusi dengan algoritma pencarian akan menghasilkan sebuah pohon dinamis berupa Pohon Ruang Status. ● Ukuran pohon akan membesar secara dinamis, sampai menemukan solusi. DFS: BFS: Inteligensi Buatan 2026 14</p>
<p>Uniform Cost Search (UCS) Uniform Cost Search (UCS) adalah algoritma yang memilih jalur berdasarkan biaya (cost) kumulatif paling kecil dari simpul awal ke suatu simpul tujuan. UCS adalah variasi dari BFS, tapi BFS menganggap semua langkah sama biayanya, sedangkan UCS memperhitungkan bobot jalur menuju solusi. Sifat: ● Complete: Ya, selama biaya langkah &gt; 0 ● Optimal: Ya, solusi dengan biaya total minimum ● Kompleksitas waktu: Bisa lebih lambat dari BFS ● Kompleksitas ruang: Boros ruang Inteligensi Buatan 2026 15</p>
<p>Uniform Cost Search (UCS) Langkah: 1. Masukkan simpul awal ke dalam priority queue (frontier set) dengan bobot 0. Set simpul awal sebagai simpul dikunjungi. 2. Ekspansi simpul-simpul yang bertetangga dengan simpul dikunjungi. Masukkan ke priority queue berdasarkan urutan bobot kumulatif terkecil. 3. Pilih simpul dalam priority queue dengan bobot kumulatif terkecil. Update bobot kumulatif. Set simpul tersebut sebagai simpul dikunjungi. 4. Ulangi langkah 2 sampai menemukan simpul tujuan. Inteligensi Buatan 2026 16</p>$qa$, 3) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s4$qa$, $qa$ib-m4$qa$, $qa$Uniform Cost Search (UCS)$qa$, $qa$<p>Uniform Cost Search (UCS) Inteligensi Buatan 2026 17</p>
<p>Uniform Cost Search (UCS) i V Frontier Dikunjungi A B C D E F G Init A {A(0)} F F F F F F F 1 A(0) {B(2), C(5)} T F F F F F F 2 B(2) {E(3), C(5), D(6)} T T F F F F F 3 E(3) {C(5), D(6), G(6)} T T F F T F F 4 C(5) {D(6), G(6), F(7)} T T T F F F F 5 D(6) {G(6), F(7)} Backtrack T T T T T F F 6 G(6) Goal T T T T T F T Awal: A Goal: G Rute: A→B→E→G Bobot = 6 Inteligensi Buatan 2026 18</p>
<p>Depth-Limited Search (DLS) Depth-Limited Search (DLS) adalah varian dari DFS yang memiliki batas kedalaman tertentu (limit depth, L). DLS akan memaksa untuk backtrack jika jalur sudah mencapai kedalaman L. Sifat: ● Complete: Tidak, jika solusi ternyata di level lebih dalam dari L ● Optimal: Tidak, solusi belum tentu paling optimal ● Kompleksitas waktu: Bergantung dengan L ● Kompleksitas ruang: Baik Inteligensi Buatan 2026 19</p>
<p>Depth-Limited Search (DLS) Inteligensi Buatan 2026 20</p>
<p>Iterative Deepening Search (IDS) Iterative Deepening Search (IDS) adalah varian dari DLS yang melakukan serangkaian DLS, dimana setiap proses DLS akan meningkatkan nilai L sampai menemukan solusi. ● DLS pertama mempunyai L = 1. DLS selanjutnya mempunyai L = 2. Dan seterusnya Sifat: ● Complete: Ya, jika b terbatas ● Optimal: Ya, jika langkah = biaya ● Kompleksitas waktu: Seperti DFS ● Kompleksitas ruang: Seperti DFS, lebih efisien dari BFS Inteligensi Buatan 2026 21</p>$qa$, 4) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s5$qa$, $qa$ib-m4$qa$, $qa$Informed Search (Heuristic Search)$qa$, $qa$<p>Informed Search (Heuristic Search) Inteligensi Buatan 2026 22</p>
<p>Informed Search (Heuristic Search) Informed Search, juga disebut Heuristic Search, adalah strategi pencarian yang memanfaatkan informasi tambahan (heuristik) agar pencarian lebih efisien. Sehingga, informasi yang agen ketahui: - keadaan awal (initial state), - keadaan tujuan (goal state), - aturan aksi yang bisa diambil, - dan nilai heuristik Inteligensi Buatan 2026 23</p>
<p>Informed Search (Heuristic Search) Karakteristik Uninformed Search: 1. Menggunakan heuristik (h(n)). Fungsinya untuk estimasi biaya/jarak dari suatu simpul n ke goal. 2. Lebih efisien. 3. Bisa optimal, Jika heuristik admissible (tidak melebih-lebihkan biaya ke tujuan) Inteligensi Buatan 2026 24</p>
<p>Informed Search (Heuristic Search) Jenis-jenis Informed Search: 1. Greedy Best-First Search, 2. A* Search Inteligensi Buatan 2026 25</p>
<p>Greedy Best-First Search (GBFS) Greedy Best-First Search adalah algoritma yang memilih node berikutnya berdasarkan perkiraan paling dekat dengan tujuan menggunakan fungsi heuristik h(n). Sifat: ● Complete: Ya, selama b terbatas ● Optimal: Tidak, karena bisa terjebak jalur yang kelihatannya dekat tapi lebih panjang. ● Kompleksitas waktu: Berpotensi eksponensial ● Kompleksitas ruang: Seperti kompleksitas waktu Inteligensi Buatan 2026 26</p>$qa$, 5) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s6$qa$, $qa$ib-m4$qa$, $qa$Greedy Best-First Search (GBFS)$qa$, $qa$<p>Greedy Best-First Search (GBFS) Inteligensi Buatan 2026 27</p>
<p>A* Search A* adalah algoritma yang menggabungkan kelebihan dari Uniform Cost Search (UCS) dan Greedy Best-First Search (GBFS). ● UCS → memperhatikan biaya nyata yang sudah ditempuh (g(n)). ● GBFS → memperhatikan perkiraan jarak ke tujuan (h(n)). Sifat: ● Complete: Ya, jika b terbatas dan bobot jalur &gt; 0 ● Optimal: Ya, jika heuristik admissible ● Kompleksitas waktu: Berpotensi eksponensial, tapi lebih baik dari BFS/DFS ● Kompleksitas ruang: Besar Inteligensi Buatan 2026 28</p>
<p>A* Search Inteligensi Buatan 2026 29</p>
<p>Contoh kasus Diberikan peta Jawa dengan kota-kota berikut, beserta jaraknya (dalam km). Berikanlah rute optimal dari Bandung ke Yogyakarta. Inteligensi Buatan 2026 30</p>
<p>Solusi A* Rute optimal: Bandung → Tasikmalaya → Purwokerto → Kebumen → Yogyakarta Dengan bobot 328 Inteligensi Buatan 2026 31</p>$qa$, 6) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s7$qa$, $qa$ib-m4$qa$, $qa$Performa Search Strategies$qa$, $qa$<p>Performa Search Strategies Beberapa perbandingan performa search strategies: Algoritma Completeness Optimality BFS (BreadthFirst Search) ✅ Ya (jika cabang terbatas) ✅ Ya (untuk bobot langkah yang sama) Menemukan solusi terpendek, tapi boros memori DFS (DepthFirst Search) ❌ Tidak (bisa terjebak di cabang tak hingga) ❌ Tidak Hemat memori, tapi tidak selalu menemukan solusi UCS (Uniform Cost Search) ✅ Ya ✅ Ya (menemukan solusi biaya minimum) Cocok untuk path cost berbeda Greedy BestFirst Search ✅ Ya (jika ada solusi) ❌ Tidak selalu (bisa terjebak optimum lokal) *tergantung heuristik Cepat, tapi tidak menjamin solusi terbaik A* Search ✅ Ya ✅ Ya (jika heuristik bisa diterima) *dapat eksponensial Paling optimal, tapi boros memori Inteligensi Buatan Time Complexity Space Complexity Keterangan Singkat 2026 32</p>
<p>Tugas Kelompok – Berbasis Kasus 01 Kasus: robot kurir kampus mencari rute dari GU (Gerbang Utama) ke LK (Lab Komputasi). Tentukan rute GU → LK menggunakan UCS, IDS, GBFS, dan A*. Gunakan bobot pada graf untuk IDS, naikkan batas kedalaman secara bertahap. Inteligensi Buatan 2026 33</p>
<p>Tugas Kelompok – Berbasis Kasus 01 Gunakan nilai h(n) berikut sebagai perkiraan jarak dari setiap simpul ke LK. Diskusikan perbedaan urutan ekspansi, rute, dan total cost yang dihasilkan oleh UCS, IDS, GBFS, dan A*. Simpul h(n) Simpul h(n) Simpul h(n) Simpul h(n) GU 12 PB 10 R 9 GKU 7 PR 6 K 9 M 7 A 4 AS 5 IF 2 SC 3 LK 0 Kode simpul: GU=Gerbang Utama, PB=Parkir Barat, R=Rektorat, GKU=Gedung Kuliah Umum, PR=Perpustakaan, K=Kantin, M=Masjid, A=Aula, AS=Asrama, IF=Teknik Informatika, SC=Sport Center, LK=Lab Komputasi. Inteligensi Buatan 2026 34</p>
<p>Tugas Kelompok – Berbasis Kasus 01 Spesifikasi: • Kelompok beranggotakan maksimal 3 mahasiswa; • Solusi dibentuk menggunakan suatu program sederhana (bahasa pemrograman dibebaskan untuk dipilih); • Pengumpulan hasil tugas kelompok dalam bentuk file PDF dengan nama file ‘TugasKelompok_Rx_nim1_nim2_nim3.pdf’, dengan fokus pembahasan: Ø Hasil luaran yang diberikan oleh program Ø Analisis perbandingan dari setiap metode yang digunakan • Durasi pengerjaan tugas kelompok ini adalah 1 Minggu dari diberikannya spesifikasi Tugas. Inteligensi Buatan 2026 35</p>
<p>Ringkasan ● Searching membantu agen menemukan urutan aksi dari keadaan awal menuju keadaan tujuan. ● Uninformed Search mencari tanpa petunjuk tambahan, sehingga urutan eksplorasi bergantung pada strategi algoritma. ● Informed Search menggunakan heuristik untuk mengarahkan pencarian ke simpul yang lebih menjanjikan. ● Pemilihan metode perlu mempertimbangkan kelengkapan, optimalitas, kompleksitas waktu, dan kompleksitas ruang. Inteligensi Buatan 2026 36</p>$qa$, 7) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.sections (id, stage_id, title, body, sort_order) values ($qa$ib-m4-s8$qa$, $qa$ib-m4$qa$, $qa$“It is better to solve one problem five different ways, than to solve five$qa$, $qa$<p>“It is better to solve one problem five different ways, than to solve five problems one way.” - George Pólya Terima Kasih…… Ada Pertanyaan? Pembahasan Berikutnya: Mg. 5 – Constraint Satisfaction Problem (CSP) Inteligensi Buatan 2026 37</p>$qa$, 8) on conflict (id) do update set stage_id = excluded.stage_id, title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
