insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$ib-m4-c2$qa$, $qa$ib-m4$qa$, $qa$checkpoint$qa$, $qa$Heuristik disebut admissible bila...$qa$, $qa$["Selalu melebihkan biaya sebenarnya", "Tidak pernah melebihkan biaya sebenarnya menuju tujuan", "Selalu bernilai nol", "Tidak memakai tujuan"]$qa$::jsonb, 1, $qa$Admissible = optimistis, tidak pernah overestimate; syarat A* optimal.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
